# Analyze each changed pair to find minimal edits
pairs = [
    ('ak', 'ek'),      # 'a' -> 'e'
    ('chxa', 'cdde'),  # 'h'->'d', 'x'->'d', 'a'->'e' 
    ('exfbec', 'edfbec'), # 'x'->'d'
    ('dxgzf', 'ddbdzzf') # 'x'->'d', 'g'->'b'
]

for i, (inp, outp) in enumerate(pairs):
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Let's manually identify differences
    min_len = min(len(inp), len(outp))

    # Find positions where characters differ
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    # Check if lengths differ
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            # Characters removed from end
            for j in range(min_len, len(inp)):
                diff_positions.append((j, inp[j], None))
        else:
            # Characters added at end  
            for j in range(min_len, len(outp)):
                diff_positions.append((j, None, outp[j]))

    print(f"  Differences: {diff_positions}")
    print()

